```python
import random
import logging
from locust import HttpUser, task, between, events

# 配置日志记录器
logging.basicConfig(level=logging.INFO)
logger = logging.getLogger("seckill_logger")

class SeckillUser(HttpUser):
    # 模拟用户的思考时间：1到3秒随机
    wait_time = between(1, 3)

    # 设置主机地址，运行时也可通过 --host 参数覆盖
    host = "http://localhost:8080"

    def on_start(self):
        """用户启动时的初始化操作"""
        self.token = None
        self.product_id = random.randint(1, 100)  # 随机初始化一个商品ID
        # 可选：用户启动时直接登录获取token，保证后续操作都有token
        # self.login()

    def get_auth_headers(self):
        """获取携带Token的请求头"""
        headers = {"Content-Type": "application/json"}
        if self.token:
            headers["Authorization"] = f"Bearer {self.token}"
        return headers

    @task(5)
    def login(self):
        """用户登录 - 权重5"""
        # 模拟不同用户登录
        payload = {
            "username": f"testuser_{random.randint(1, 10000)}",
            "password": "password123"
        }
        with self.client.post("/api/auth/login", json=payload, catch_response=True) as response:
            if response.status_code == 200:
                # 假设返回结构为 {"code": 200, "data": {"token": "xxx"}}
                try:
                    res_json = response.json()
                    self.token = res_json.get("data", {}).get("token")
                    if self.token:
                        response.success()
                    else:
                        response.failure("登录成功但未返回Token")
                except ValueError:
                    response.failure("登录响应非JSON格式")
            else:
                response.failure(f"登录失败，状态码: {response.status_code}")

    @task(10)
    def browse_products(self):
        """浏览商品列表 - 权重10"""
        with self.client.get("/api/products", headers=self.get_auth_headers(), catch_response=True) as response:
            if response.status_code == 200:
                try:
                    # 随机提取一个商品ID供后续查看详情和秒杀使用
                    products = response.json().get("data", [])
                    if products and isinstance(products, list):
                        self.product_id = random.choice(products).get("id", self.product_id)
                    response.success()
                except Exception:
                    response.failure("解析商品列表失败")
            else:
                response.failure(f"获取商品列表失败，状态码: {response.status_code}")

    @task(8)
    def view_product_detail(self):
        """查看商品详情 - 权重8"""
        url = f"/api/products/{self.product_id}"
        with self.client.get(url, headers=self.get_auth_headers(), catch_response=True) as response:
            if response.status_code == 200:
                response.success()
            elif response.status_code == 404:
                # 商品不存在不算接口错误，但业务上可标记为失败
                response.failure(f"商品ID {self.product_id} 不存在")
            else:
                response.failure(f"获取商品详情失败，状态码: {response.status_code}")

    @task(2)
    def seckill(self):
        """参与秒杀 - 权重2"""
        if not self.token:
            # 如果没有登录，直接跳过或先触发登录
            logger.warning("用户未登录，尝试参与秒杀被拒绝。")
            return

        payload = {"product_id": self.product_id}
        with self.client.post("/api/seckill/start", json=payload, headers=self.get_auth_headers(), catch_response=True) as response:
            # 秒杀场景通常会有业务层面的失败（如库存不足、活动未开始等）
            if response.status_code == 200:
                response.success()
            else:
                # 秒杀失败时记录详细日志
                error_msg = f"秒杀失败 | 商品ID: {self.product_id} | 状态码: {response.status_code} | 响应: {response.text}"
                logger.error(error_msg)
                response.failure(error_msg)

    @task(3)
    def query_orders(self):
        """查询订单 - 权重3"""
        with self.client.get("/api/orders", headers=self.get_auth_headers(), catch_response=True) as response:
            if response.status_code == 200:
                response.success()
            else:
                response.failure(f"查询订单失败，状态码: {response.status_code}")

